                          ) -> Optional[Tuple[str, str]]:
    """Cherche le CSV de relevements le plus pertinent."""
    if not imported_files:
        return None
    csvs = [(n, c) for n, c in imported_files if n.lower().endswith(".csv")]
    if not csvs:
        return None
    for name, content in reversed(csvs):
